import { defineConfig } from 'drizzle-kit';

// drizzle-kit loads this file as CJS (no top-level await), so read the root `.env` — generated by
// `pnpm dev` / `pnpm test` — synchronously. Run from apps/api (via `pnpm db:generate`).
process.loadEnvFile('../../.env');

export default defineConfig({
  dialect: 'postgresql',
  schema: './src/db/schema.ts',
  out: './drizzle',
  dbCredentials: { url: process.env.DATABASE_URL ?? '' },
});
